// Deterministic pure-JS 4h conditional pullback experiment; input completed OHLCV and historical funding rows.
function smokeTest(){
 const a=Array.from({length:80},(_,i)=>({o:100+i*.1,h:101+i*.1,l:99+i*.1,c:100.2+i*.1}));
 const e=(i,p,b)=>{let v=b[0].c,k=2/(p+1);for(let j=1;j<=i;j++)v=b[j].c*k+v*(1-k);return v;};
 const sig=(i,b)=>e(i,20,b)>e(i,50,b)&&e(i,50,b)>e(i-5,50,b)&&b[i].c>e(i,20,b);
 const x=sig(60,a),m=a.map(z=>({...z}));m[70]={o:1,h:99999,l:1,c:99999};
 return{passed:x===sig(60,a)&&x===sig(60,m),deterministic:x===sig(60,a),noLookahead:x===sig(60,m),fixtureBars:a.length};
}
function runExperiment({series,funding}){
 const indicator=bars=>{
  const c=bars.map(x=>x.c),e20=ema(c,20),e50=ema(c,50);
  const tr=bars.map((x,i)=>i===0?x.h-x.l:Math.max(x.h-x.l,Math.abs(x.h-bars[i-1].c),Math.abs(x.l-bars[i-1].c)));
  const atr=bars.map((_,i)=>i<13?null:tr.slice(i-13,i+1).reduce((a,x)=>a+x,0)/14);
  const ret=bars.map((x,i)=>i===0?null:Math.abs(x.c/bars[i-1].c-1));
  const strength=bars.map((_,i)=>atr[i]?Math.abs(e20[i]-e50[i])/atr[i]:null);
  const atrPct=bars.map((x,i)=>atr[i]?atr[i]/x.c:null);
  const trend=bars.map((_,i)=>i<5?0:e20[i]>e50[i]&&e50[i]>e50[i-5]?1:e20[i]<e50[i]&&e50[i]<e50[i-5]?-1:0);
  return{e20,e50,atr,ret,strength,atrPct,trend};
 };
 const rng=seed=>{let s=seed>>>0;return()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296;};};
 const bootstrap=trades=>{
  if(!trades.length)return{ci95:[null,null],pPositive:null,pNegative:null,iterations:0,blockTrades:3};
  const values=trades.map(t=>t.r),mean=values.reduce((a,x)=>a+x,0)/values.length,random=rng(23),dist=[],nullDist=[],block=Math.min(3,values.length);
  for(let k=0;k<2000;k++){
   const sample=[],centered=[];
   while(sample.length<values.length){
    const start=Math.floor(random()*values.length);
    for(let j=0;j<block&&sample.length<values.length;j++){
     const v=values[(start+j)%values.length];sample.push(v);centered.push(v-mean);
    }
   }
   dist.push(sample.reduce((a,x)=>a+x,0)/sample.length);
   nullDist.push(centered.reduce((a,x)=>a+x,0)/centered.length);
  }
  dist.sort((a,b)=>a-b);
  return{ci95:[quantile(dist,.025),quantile(dist,.975)],pPositive:(nullDist.filter(x=>x>=mean).length+1)/(nullDist.length+1),pNegative:(nullDist.filter(x=>x<=mean).length+1)/(nullDist.length+1),iterations:2000,blockTrades:block};
 };
 const simulate=(bars,a,b,f,th,start,end,tol)=>{
  const trades=[];let equity=10000,i=Math.max(start,55);
  const fee=.0005,impact=.00025,riskPct=.005,maxLev=3,stopATR=1.5,targetR=2,timeStop=12;
  while(i<=end-timeStop){
   const d=a.trend[i],atr=a.atr[i],strength=a.strength[i],shock=a.ret[i];
   if(!d||d!==b.trend[i]||!atr||strength<th.strength||shock>th.shock){i++;continue;}
   const x=bars[i],long=d===1,pull=long?(x.l<=a.e20[i]+tol*atr&&x.c>a.e20[i]&&x.c>x.o):(x.h>=a.e20[i]-tol*atr&&x.c<a.e20[i]&&x.c<x.o);
   if(!pull){i++;continue;}
   const entryBar=bars[i+1],rawEntry=entryBar.o,riskDist=stopATR*atr,stop=rawEntry-d*riskDist,target=rawEntry+d*targetR*riskDist;
   const entryFill=rawEntry*(1+d*impact),riskBudget=equity*riskPct,qty=Math.min(riskBudget/riskDist,equity*maxLev/entryFill);
   if(!(qty>0)){i++;continue;}
   let exitRaw=null,reason="TIME",exitIndex=i+timeStop;
   for(let j=i+1;j<=i+timeStop;j++){
    const z=bars[j];
    if(long){if(z.l<=stop){exitRaw=z.o<stop?z.o:stop;reason="STOP";exitIndex=j;break;}if(z.h>=target){exitRaw=target;reason="TARGET";exitIndex=j;break;}}
    else{if(z.h>=stop){exitRaw=z.o>stop?z.o:stop;reason="STOP";exitIndex=j;break;}if(z.l<=target){exitRaw=target;reason="TARGET";exitIndex=j;break;}}
   }
   if(exitRaw===null)exitRaw=bars[exitIndex].c;
   const exitBar=bars[exitIndex],exitFill=exitRaw*(1-d*impact),notional=entryFill*qty,exitNotional=exitFill*qty,fees=(notional+exitNotional)*fee;
   let fundingCost=0,fundingEvents=0;
   for(const fr of f)if(fr.t>entryBar.t&&fr.t<=exitBar.ct){fundingCost+=d*fr.rate*notional;fundingEvents++;}
   const pnl=d*(exitFill-entryFill)*qty-fees-fundingCost,r=pnl/(riskDist*qty);
   let mae=0;for(let j=i+1;j<=exitIndex;j++){const z=bars[j],adv=long?rawEntry-z.l:z.h-rawEntry;mae=Math.max(mae,adv/riskDist);}
   trades.push({entryTime:entryBar.t,exitTime:exitBar.ct,side:d,reason,pnl,r,holdBars:exitIndex-i,notional,fundingCost,fees,maeR:mae,fundingEvents,entry:rawEntry,exit:exitRaw});
   equity+=pnl;i=exitIndex+1;
  }
  return trades;
 };
 const summarize=(trades,segment,from,to)=>{
  const wins=trades.filter(t=>t.pnl>0),losses=trades.filter(t=>t.pnl<0),gw=wins.reduce((a,t)=>a+t.pnl,0),gl=Math.abs(losses.reduce((a,t)=>a+t.pnl,0));
  let eq=10000,peak=10000,dd=0;for(const t of trades){eq+=t.pnl;peak=Math.max(peak,eq);dd=Math.max(dd,(peak-eq)/peak*100);}
  return{trades:trades.length,segmentBars:segment.length,winRatePct:trades.length?wins.length/trades.length*100:null,targetBeforeStopPct:trades.length?trades.filter(t=>t.reason==="TARGET").length/trades.length*100:null,expectancyR:trades.length?trades.reduce((a,t)=>a+t.r,0)/trades.length:null,profitFactor:gl?gw/gl:(gw?null:0),netPnlUSDT:trades.reduce((a,t)=>a+t.pnl,0),netReturnPct:(eq/10000-1)*100,maxDrawdownPct:dd,averageWinUSDT:wins.length?gw/wins.length:null,averageLossUSDT:losses.length?losses.reduce((a,t)=>a+t.pnl,0)/losses.length:null,averageHoldBars:trades.length?trades.reduce((a,t)=>a+t.holdBars,0)/trades.length:null,exposurePct:segment.length?trades.reduce((a,t)=>a+t.holdBars,0)/segment.length*100:null,turnoverX:trades.reduce((a,t)=>a+t.notional*2,0)/10000,fundingNetUSDT:trades.reduce((a,t)=>a+t.fundingCost,0),fundingEventsApplied:trades.reduce((a,t)=>a+t.fundingEvents,0),maxMAE_R:trades.length?Math.max(...trades.map(t=>t.maeR)):null,bootstrap:bootstrap(trades)};
 };
 const baseline=(bars,a,start,end)=>{
  const bh=(bars[end].c/bars[start].o-1-.0015)*100;let eq=1,prev=0,flips=0;
  for(let i=start+1;i<=end;i++){const side=a.trend[i-1],ret=side?side*(bars[i].c/bars[i-1].c-1):0;if(side!==prev){const legs=(prev===0||side===0)?1:2;eq*=1-.00075*legs;flips++;}eq*=1+ret;prev=side;}
  if(prev!==0)eq*=1-.00075;
  return{buyHoldNetReturnPct:bh,emaTrendNetReturnPct:(eq-1)*100,emaTrendTransitions:flips};
 };
 const context=(bars,a,b,th,start,end)=>{
  const trend={BULL:0,BEAR:0,TRANSITION:0},vol={LOW:0,NORMAL:0,HIGH:0},btc={CONFIRM:0,DIVERGE:0,UNKNOWN:0},transitions={},labels=[];
  for(let i=start;i<=end;i++){const d=a.trend[i],lab=d===1?"BULL":d===-1?"BEAR":"TRANSITION",v=a.atrPct[i],vl=v<=th.volLow?"LOW":v>=th.volHigh?"HIGH":"NORMAL",bl=!d||!b.trend[i]?"UNKNOWN":d===b.trend[i]?"CONFIRM":"DIVERGE";trend[lab]++;vol[vl]++;btc[bl]++;labels.push(lab);}
  let runs=[],len=0,prev=labels[0],switches=0;
  for(const lab of labels){if(lab===prev)len++;else{runs.push(len);transitions[prev+"->"+lab]=(transitions[prev+"->"+lab]||0)+1;len=1;prev=lab;switches++;}}
  if(len)runs.push(len);
  return{trendBars:trend,volatilityBars:vol,btcAlignmentBars:btc,trendTransitions:switches,transitionCounts:transitions,meanTrendDurationBars:runs.length?runs.reduce((a,x)=>a+x,0)/runs.length:null,contextBars:labels.length};
 };
 const n=series.BTCUSDT.length,trainEnd=Math.floor(n*.6),valEnd=Math.floor(n*.8),testStart=valEnd,testEnd=n-1,out={};
 for(const s of ["ETHUSDT","SOLUSDT","XRPUSDT"]){
  const bars=series[s],a=indicator(bars),b=indicator(series.BTCUSDT),fit=Array.from({length:trainEnd-55},(_,j)=>j+55);
  const th={strength:quantile(fit.map(i=>a.strength[i]),.6),volLow:quantile(fit.map(i=>a.atrPct[i]),.25),volHigh:quantile(fit.map(i=>a.atrPct[i]),.75),shock:quantile(fit.map(i=>a.ret[i]),.99)};
  const eligible=(lo,hi)=>{let count=0;for(let i=lo;i<=hi-12;i++)if(a.trend[i]&&a.trend[i]===b.trend[i]&&a.strength[i]>=th.strength&&a.ret[i]<=th.shock)count++;return count;};
  const tr=simulate(bars,a,b,funding[s],th,55,trainEnd-1,.25),va=simulate(bars,a,b,funding[s],th,trainEnd,valEnd-1,.25),te=simulate(bars,a,b,funding[s],th,testStart,testEnd,.25);
  const train=summarize(tr,bars.slice(55,trainEnd),bars[55].t,bars[trainEnd-1].ct),validation=summarize(va,bars.slice(trainEnd,valEnd),bars[trainEnd].t,bars[valEnd-1].ct),test=summarize(te,bars.slice(testStart),bars[testStart].t,bars[testEnd].ct);
  test.eligibleContextObservations=eligible(testStart,testEnd);
  test.tradeLog=te.map(t=>({entryUtc:new Date(t.entryTime).toISOString(),exitUtc:new Date(t.exitTime).toISOString(),side:t.side,exitReason:t.reason,netPnlUSDT:t.pnl,netR:t.r,holdBars:t.holdBars,fundingEvents:t.fundingEvents,fundingCostUSDT:t.fundingCost,feesUSDT:t.fees,maxMAE_R:t.maeR}));
  const s15=simulate(bars,a,b,funding[s],th,testStart,testEnd,.15),s35=simulate(bars,a,b,funding[s],th,testStart,testEnd,.35);
  out[s]={trainingThresholds:th,splits:{train:{from:new Date(bars[55].t).toISOString(),to:new Date(bars[trainEnd-1].ct).toISOString(),bars:trainEnd-55},validation:{from:new Date(bars[trainEnd].t).toISOString(),to:new Date(bars[valEnd-1].ct).toISOString(),bars:valEnd-trainEnd},untouchedTest:{from:new Date(bars[testStart].t).toISOString(),to:new Date(bars[testEnd].ct).toISOString(),bars:testEnd-testStart+1}},train,validation,test,context:context(bars,a,b,th,testStart,testEnd),baseline:baseline(bars,a,testStart,testEnd),sensitivity:{tol015:{trades:s15.length,expectancyR:s15.length?s15.reduce((x,t)=>x+t.r,0)/s15.length:null},tol025:{trades:te.length,expectancyR:test.expectancyR},tol035:{trades:s35.length,expectancyR:s35.length?s35.reduce((x,t)=>x+t.r,0)/s35.length:null}},fundingCoverage:{rows:funding[s].length,first:new Date(funding[s][0].t).toISOString(),last:new Date(funding[s].at(-1).t).toISOString()}};
 }
 return{barsPerSymbol:n,trainEnd,valEnd,testStart,testEnd,symbols:out};
}
